document.addEventListener("DOMContentLoaded", function () {
    console.log("Script loaded, DOM is ready!"); // ✅ Step 1: Debug if script runs

    frappe.ready(() => {
        console.log("Frappe is ready!"); // ✅ Step 2: Debug if frappe is loaded

        frappe.web_form.on("language", (field, value) => {
            console.log("Language selected:", value); // ✅ Step 3: Debug when language changes

            let file_links = {
                "English": "/files/Code of Condact ENG Occupational Health and Safety Standards and Internal Regulations.pdf",
                "Swedish": "/files/Code of Condact SWE Arbetsskydd normer och interna ordningsregler.pdf",
                "Romanian": "/files/Code of Condact RUM Norme de protecție a muncii V1.pdf",
                "Thai": "/files/Code of Condact THAI นี่คือการแปลข้อความที่ให้มาเป็นภาษาไทย.pdf"
            };

            let file_url = file_links[value];

            if (file_url) {
                console.log("File URL:", file_url); // ✅ Step 4: Debug if correct file URL is selected

                // Select the existing HTML field
                let html_field = document.querySelector('.frappe-control[data-fieldtype="HTML"] .control-input');

                if (html_field) {
                    console.log("HTML field found"); // ✅ Step 5: Debug if the HTML field exists
                    html_field.innerHTML = `<a href="${file_url}" target="_blank" style="color: blue; text-decoration: underline;">📄 Open Document</a>`;
                } else {
                    console.log("HTML field not found, creating new element"); // ✅ Step 6: Debug when HTML field is missing

                    // If HTML field doesn't exist, create a new link
                    let new_link = document.createElement("div");
                    new_link.innerHTML = `<a href="${file_url}" target="_blank" style="color: blue; text-decoration: underline;">📄 Open Document</a>`;
                    new_link.id = "file-link";

                    let parentElement = frappe.web_form.wrapper;
                    let existingLink = document.getElementById("file-link");

                    if (existingLink) {
                        existingLink.remove(); // Remove old link
                    }

                    parentElement.appendChild(new_link);
                }
            } else {
                console.log("No file found for selected language"); // ✅ Step 7: Debug if no file is found
            }
        });
    });
});
